294	pub fn types_equal(a: Type, b: Type) -> Bool {
295	    match a {
296	        Type::IntType => match b { Type::IntType => true, _ => false },
297	        Type::FloatType => match b { Type::FloatType => true, _ => false },
298	        Type::StrType => match b { Type::StrType => true, _ => false },
299	        Type::BoolType => match b { Type::BoolType => true, _ => false },
300	        Type::UnitType => match b { Type::UnitType => true, _ => false },
301	        Type::NeverType => match b { Type::NeverType => true, _ => false },
302	        Type::AnyType => match b { Type::AnyType => true, _ => false },
303	        Type::ErrorType => match b { Type::ErrorType => true, _ => false },
304	        Type::TypeVar { id: id_a, .. } => match b {
305	            Type::TypeVar { id: id_b, .. } => id_a == id_b,
306	            _ => false
307	        },
308	        Type::FnType { params: pa, return_type: ra, effects: ea } => match b {
309	            Type::FnType { params: pb, return_type: rb, effects: eb } =>
310	                type_lists_equal(pa, pb) && types_equal(ra, rb)
311	                    && effects_list_equal(ea.effects, eb.effects)
312	                    // Open effect row tails are compared by exact TypeVar ID (structural equality).
313	                    // Two different open tails (?N1, ?N2) are structurally distinct even though both
314	                    // represent "open row" semantically. Semantic equivalence is handled by unification,
315	                    // not types_equal — this function is for error messages and debug output.
316	                    && optional_ids_equal(ea.tail, eb.tail),
317	            _ => false
318	        },
319	        Type::StructType { name: na, type_params: tpa, .. } => match b {
320	            Type::StructType { name: nb, type_params: tpb, .. } =>
321	                na == nb && type_lists_equal(tpa, tpb),
322	            _ => false
323	        },
324	        Type::EnumType { name: na, type_params: tpa, .. } => match b {
325	            Type::EnumType { name: nb, type_params: tpb, .. } =>
326	                na == nb && type_lists_equal(tpa, tpb),
327	            _ => false
328	        },
329	        Type::GenericType { base: ba, args: aa } => match b {
330	            Type::GenericType { base: bb, args: ab } =>
331	                types_equal(ba, bb) && type_lists_equal(aa, ab),
332	            _ => false
333	        },
334	        // Record fields are compared as unordered sets (row polymorphism semantics).
335	        // Field order does not affect type equality, unlike TupleType where position matters.
336	        Type::RecordType { fields: fa, tail: ta, .. } => match b {
337	            Type::RecordType { fields: fb, tail: tb, .. } => {
338	                if fa.len() != fb.len() { return false }
339	                if !optional_ids_equal(ta, tb) { return false }
340	                fa.all(fn(f) {
341	                    fb.any(fn(bf) { bf.name == f.name && types_equal(f.ty, bf.ty) })
342	                })
343	            },
344	            _ => false
345	        },
346	        Type::EffectRowType { effects: ea, tail: ta } => match b {
347	            Type::EffectRowType { effects: eb, tail: tb } => {
348	                if !optional_ids_equal(ta, tb) { return false }
349	                if ea.len() != eb.len() { return false }
350	                ea.all(fn(ae) { eb.any(fn(be) { effects_equal(ae, be) }) })
351	            },
352	            _ => false
353	        },
354	        Type::TupleType { elements: ea } => match b {
355	            Type::TupleType { elements: eb } => type_lists_equal(ea, eb),
356	            _ => false
357	        }
358	    }
359	}
