364	        Type::FloatType => BUILTIN_FLOAT,
365	        Type::StrType => BUILTIN_STR,
366	        Type::BoolType => BUILTIN_BOOL,
367	        Type::UnitType => "()",
368	        Type::NeverType => "Never",
369	        Type::AnyType => "Any",
