371	            some(n) => n,
372	            none => "?${id.to_str()}"
373	        },
374	        Type::FnType { params, return_type, effects } => {
375	            let ps = params.map(fn(p) { type_to_string(p) }).join(", ")
376	            let ret = type_to_string(return_type)
377	            let eff = effect_row_to_string(effects)
378	            if eff.len() > 0 { "(${ps}) -> ${ret} / ${eff}" }
379	            else { "(${ps}) -> ${ret}" }
380	        },
381	        Type::StructType { name, type_params, .. } => {
382	            if type_params.len() == 0 { name }
383	            else { "${name}<${type_params.map(fn(p) { type_to_string(p) }).join(", ")}>" }
384	        },
385	        Type::EnumType { name, type_params, .. } => {
386	            if name == BUILTIN_OPTION && type_params.len() == 1 {
387	                "${type_to_string(type_params.first().unwrap_or(UNIT))}?"
388	            } else if type_params.len() == 0 { name }
389	            else { "${name}<${type_params.map(fn(p) { type_to_string(p) }).join(", ")}>" }
390	        },
391	        Type::GenericType { base, args } => {
392	            "${type_to_string(base)}<${args.map(fn(a) { type_to_string(a) }).join(", ")}>"
393	        },
394	        Type::RecordType { fields, tail, tail_name } => {
395	            let fs = fields.map(fn(f) { "${f.name}: ${type_to_string(f.ty)}" }).join(", ")
396	            match tail {
397	                some(t) => {
398	                    let ts = match tail_name { some(n) => n, none => "?${t.to_str()}" }
399	                    if fs.len() > 0 { "{${fs}, ..${ts}}" } else { "{..${ts}}" }
400	                },
401	                none => "{${fs}}"
402	            }
403	        },
404	        Type::EffectRowType { effects, tail } => {
405	            let es = effects.map(fn(e) { effect_to_string(e) }).join(", ")
406	            match tail {
407	                some(t) => "<${es}, ?${t.to_str()}>",
408	                none => "<${es}>"
409	            }
410	        },
411	        Type::TupleType { elements } =>
412	            "(${elements.map(fn(e) { type_to_string(e) }).join(", ")})",
413	        Type::ErrorType => "<error>"

