1	// B-101 native self-compile E2E harness.
2	//
3	// PURPOSE — the permanent regression net for native-frontend self-hosting that
4	// `a_empty.ring` (trivial program) could not catch. Compiles a REAL program that
5	// stresses the std surfaces most exposed to RC over-free / leak bugs under the
6	// clone-all-escape borrow model — print, List (push/index/iterate/join), Map
7	// (insert/index/get/iterate), Str (interp/index/len), plus element-READ
8	// projections bound to `let` (the B-101 alias-aware-ownership hot path) — using the
9	// NATIVE ring.exe (the self-compiled native compiler binary), then runs the result
10	// and asserts EXIT 0 + exact stdout.
11	//
12	// HOW THE ORCHESTRATOR RUNS THIS (main repo, with the LLVM toolchain present):
13	//   cd compiler && node --test ../tests/native_selfcompile.test.mjs
14	// or wire it into an npm script (e.g. `npm run test:native`).
15	//
16	// WHAT IT ASSERTS:
17	//   1. native ring.exe compiles tests/native/real_program.ring WITHOUT crashing
18	//      (exit 0 from the build step), via `ring.exe build <prog> --target=js` — the
19	//      native frontend self-hosts the JS backend (the native LLVM backend is B-099,
20	//      not yet linked; --target=js exercises the full native frontend: lexer →
21	//      parser → checker → HIR → Perceus → JS codegen, all running as native code).
22	//   2. The produced JS runs to EXIT 0 and prints EXACTLY EXPECTED_STDOUT.
23	//   3. Steps 1+2 are repeated 3× and every run must be identical — per the
24	//      intermittent-heap-corruption lesson (a single pass can mask a ~1/3-hit
25	//      RC bug), an RC regression that only sometimes corrupts the heap is caught.
26	//
27	// WHY --target=js AND NOT --target=llvm: per docs/backlog.md (B-099), the native
28	// binary self-hosts the FRONTEND via --target=js; emitting native code FROM the
29	// native binary (--target=llvm needing libLLVM-C linkage) is B-099, out of B-101
30	// scope. The RC model under test (Perceus) is a HIR-level pass shared by both
31	// backends and fully exercised by the native frontend regardless of emit target.
32	// If the orchestrator additionally has the native LLVM backend wired, swap
33	// BUILD_ARGS to ["build", PROG, "--target=llvm"] + link + run the .exe; the
34	// EXPECTED_STDOUT is identical (JS backend is the oracle, see the .ring fixture).
35	//
36	// SKIP BEHAVIOR (this worktree): ring.exe is built from compiler/dist-llvm/main.o +
37	// ring_runtime.o and is UNTRACKED (gitignored local artifact); the LLVM N-API addon
38	// (compiler/llvm-addon/) is also a local build. A fresh worktree has neither, so
39	// ring.exe is absent — every test then SKIPS rather than fails. The harness never
40	// attempts to BUILD ring.exe (that would stall on the addon build); it only USES a
41	// pre-built ring.exe if one is present at the repo root.
42	
43	import { test, describe } from "node:test";
44	import assert from "node:assert/strict";
45	import * as fs from "node:fs";
46	import * as path from "node:path";
47	import { spawnSync } from "node:child_process";
48	import { fileURLToPath } from "node:url";
49	
50	const __dirname = path.dirname(fileURLToPath(import.meta.url));
51	const REPO = path.resolve(__dirname, "..");
52	
53	// Native compiler binary, produced by:
54	//   node compiler/dist/main.js build compiler/main.ring --out-dir=compiler/dist-llvm --target=llvm
55	//   clang compiler/dist-llvm/main.o ring_runtime.o -o ring.exe -lmsvcrt
56	// Untracked local artifact — present in the main repo after a native bootstrap,
57	// absent in a fresh worktree.
58	const RING_EXE = path.join(REPO, process.platform === "win32" ? "ring.exe" : "ring");
59	const HAVE_RING_EXE = fs.existsSync(RING_EXE);
60	
61	const PROG = path.join(REPO, "tests", "native", "real_program.ring");
62	
63	// Pinned by the JS oracle (build tests/native/real_program.ring with the JS
64	// backend and run it). The native build must reproduce this byte-for-byte.
65	const EXPECTED_STDOUT = [
66	  "count=3",
67	  "ada,bob,cleo",
68	  "top=ada (90)",
69	  "sum=163",
70	  "first=r len=4",
71	  "total=253",
72	].join("\n");
73	
74	const RUNS = 3; // intermittent-RC detection: a ~1/3-hit heap bug needs >1 run.
75	
76	// Normalize line endings: the native binary may write CRLF via Windows text-mode
77	// stdout; compare logical output, not byte encoding. Also trim a single trailing
78	// newline so the assertion is independent of whether print() appends one at EOF.
79	function norm(s) {
80	  return s.replace(/\r\n/g, "\n").replace(/\n$/, "");
81	}
82	
83	// Build the fixture with the NATIVE ring.exe (frontend self-host via --target=js),
84	// then run the emitted JS. Returns { code, stdout } of the program run, or throws
85	// with diagnostics if the native build step itself crashed (non-zero exit).
86	function buildAndRunNative() {
87	  const jsOut = PROG.replace(/\.ring$/, ".js");
88	  try {
89	    const build = spawnSync(RING_EXE, ["build", PROG, "--target=js"], {
90	      cwd: REPO, encoding: "utf-8", timeout: 120000,
91	    });
92	    assert.strictEqual(build.status, 0,
93	      `native ring.exe build FAILED (exit ${build.status})\n` +
94	      `--- stdout ---\n${build.stdout}\n--- stderr ---\n${build.stderr}`);
95	    assert.ok(fs.existsSync(jsOut),
96	      `native build reported success but produced no JS at ${jsOut}`);
97	
98	    const run = spawnSync(process.execPath, [jsOut], {
99	      cwd: REPO, encoding: "utf-8", timeout: 60000,
100	    });
101	    return { code: run.status, stdout: run.stdout, stderr: run.stderr };
102	  } finally {
103	    fs.rmSync(jsOut, { force: true });
104	  }
105	}
106	
107	describe("native self-compile E2E (B-101)", () => {
108	  for (let i = 1; i <= RUNS; i++) {
109	    test(`real_program via native ring.exe — run ${i}/${RUNS}`,
110	      { skip: HAVE_RING_EXE ? false : "ring.exe not present (build native compiler first)" },
111	      () => {
112	        const { code, stdout, stderr } = buildAndRunNative();
113	        assert.strictEqual(code, 0,
114	          `native-compiled program did NOT exit 0 (exit ${code}) — likely RC over-free/abort\n` +
115	          `--- stdout ---\n${stdout}\n--- stderr ---\n${stderr}`);
116	        assert.strictEqual(norm(stdout), EXPECTED_STDOUT,
117	          `native-compiled program stdout diverged from oracle\n` +
118	          `--- expected ---\n${EXPECTED_STDOUT}\n--- got ---\n${norm(stdout)}`);
119	      });
120	  }
121	});
