$tmp = Join-Path $env:TEMP "ring_sc_lbb"; New-Item -ItemType Directory -Force $tmp | Out-Null
$outlog = Join-Path $env:TEMP "ring_lbb_out.txt"; $errlog = Join-Path $env:TEMP "ring_lbb_err.txt"
$ceiling = 15GB
$t0 = [Environment]::TickCount
$p = Start-Process -FilePath ".\ring.exe" -ArgumentList @("build","compiler/main.ring","--target=js","--out-dir=$tmp") -PassThru -NoNewWindow -RedirectStandardOutput $outlog -RedirectStandardError $errlog
$peak = 0; $killed = $false; $samples = @(); $i = 0
while (-not $p.HasExited) {
    Start-Sleep -Milliseconds 400
    try { $p.Refresh(); $cur = $p.WorkingSet64; $pk = $p.PeakWorkingSet64 } catch { break }
    if ($pk -gt $peak) { $peak = $pk }
    $i++; if ($i % 3 -eq 0) { $el = [math]::Round(([Environment]::TickCount - $t0)/1000,1); $samples += "${el}s=$([math]::Round($cur/1GB,2))" }
    if ($cur -gt $ceiling) { $killed = $true; $p.Kill(); break }
}
if (-not $killed) { $p.WaitForExit(); try { if ($p.PeakWorkingSet64 -gt $peak) { $peak = $p.PeakWorkingSet64 } } catch {} }
$secs = [math]::Round(([Environment]::TickCount - $t0)/1000,1)
$exitstr = if ($killed) { "KILLED@15GB" } else { "$($p.ExitCode)" }
